
#!/usr/bin/env python3
import base64,os
print("Deploying AI dispatch fix...")
e=[]
try:
  os.makedirs(os.path.dirname("/workspaces/Sonalit/backend/src/routes/ai.js"),exist_ok=True)
  open("/workspaces/Sonalit/backend/src/routes/ai.js","wb").write(base64.b64decode(""))
  print("  OK ai.js")
except Exception as x: e.append("ai.js:"+str(x))
try:
  os.makedirs(os.path.dirname("/workspaces/Sonalit/frontend/src/components/CommandBar.jsx"),exist_ok=True)
  open("/workspaces/Sonalit/frontend/src/components/CommandBar.jsx","wb").write(base64.b64decode(""))
  print("  OK CommandBar.jsx")
except Exception as x: e.append("CommandBar.jsx:"+str(x))
try:
  os.makedirs(os.path.dirname("/workspaces/Sonalit/frontend/src/components/Layout.jsx"),exist_ok=True)
  open("/workspaces/Sonalit/frontend/src/components/Layout.jsx","wb").write(base64.b64decode(""))
  print("  OK Layout.jsx")
except Exception as x: e.append("Layout.jsx:"+str(x))
try:
  os.makedirs(os.path.dirname("/workspaces/Sonalit/frontend/src/services/api.js"),exist_ok=True)
  open("/workspaces/Sonalit/frontend/src/services/api.js","wb").write(base64.b64decode(""))
  print("  OK api.js")
except Exception as x: e.append("api.js:"+str(x))
if e: print("ERRORS:",e)
else: print("\nDone! Now restart backend: kill -9 $(lsof -t -i:5000) 2>/dev/null; cd /workspaces/Sonalit/backend && npm run dev")